using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class InspectCustomMotionUnits {public static object Main(){var rows=new List<object>();string root="Assets/ShooterSurvival/Models/Chapters/Chapters45/DetailedCharacters20261003/";foreach(string id in new[]{"CH01","CH02"}){var body=AssetDatabase.LoadAssetAtPath<GameObject>(root+id+"/body.fbx");foreach(string name in new[]{"idle","attack_once","dribble"}){var c=AssetDatabase.LoadAssetAtPath<AnimationClip>(root+id+"/"+name+".anim");if(c==null)continue;foreach(string path in new[]{"Armature","Armature/Hips","Armature/Hips/Spine02","Armature/Hips/LeftUpLeg","Armature/Hips/Spine02/Spine01/Spine/RightShoulder/RightArm/RightForeArm"}){var t=body.transform.Find(path);rows.Add(new{id,name,path,rest=new[]{t.localPosition.x,t.localPosition.y,t.localPosition.z},scale=new[]{t.localScale.x,t.localScale.y,t.localScale.z},euler=new[]{t.localEulerAngles.x,t.localEulerAngles.y,t.localEulerAngles.z},curves=AnimationUtility.GetCurveBindings(c).Where(b=>b.path==path&&b.propertyName.StartsWith("m_LocalPosition")).Select(b=>new{b.propertyName,first=AnimationUtility.GetEditorCurve(c,b).Evaluate(0),last=AnimationUtility.GetEditorCurve(c,b).Evaluate(c.length)}).ToArray()});}}}return new{items=rows};}}
